{"hypotheses": [
  {
    "name": "Quality-Momentum Divergence",
    "mechanism": "Combining high profitability (OperProf) and recent momentum (Mom12m), while offsetting asset growth (AssetGrowth), targets stocks with persistent profitability and price trends, but avoids those whose momentum is purely from aggressive investment. The interaction exploits the tendency for momentum to be stronger among quality firms, but avoids overvalued growth traps.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OperProf"},
        {"weight": 1.0, "primitive": "Mom12m"},
        {"weight": -0.5, "primitive": "AssetGrowth"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "BM", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 1.0,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Low Volatility Value Rotation",
    "mechanism": "This composite combines classic value (BM) and low volatility (RealizedVol, inversed), favoring undervalued, less volatile stocks. By emphasizing value in low-vol regimes, it captures the anomaly that low-risk value stocks tend to outperform, especially when market fear is muted and investors are less focused on downside risk.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BM"},
        {"weight": -1.0, "primitive": "RealizedVol"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "correlation", "primitive": "Beta", "bound": "below", "threshold": 0.3},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Repurchase-Momentum Synergy",
    "mechanism": "Firms engaging in share repurchases (ShareRepurchase) and with positive intermediate momentum (Mom6m) may signal undervaluation and strong future prospects. Offsetting with short interest (ShortInterest) helps avoid crowded shorts and excessive optimism, focusing on stocks with both positive insider signals and price trends.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ShareRepurchase"},
        {"weight": 0.5, "primitive": "Mom6m"},
        {"weight": -0.5, "primitive": "ShortInterest"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "Mom12m", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.9,
    "expected_decay_half_life_months": null
  },
  {
    "name": "Earnings Revision-Illiquidity Contrarian",
    "mechanism": "The strategy combines positive EPS forecast revisions (AnalystRevision) with a short leg in illiquid stocks (Illiquidity), betting that upward analyst revisions are more effective in liquid stocks where information is impounded quickly. It captures the idea that illiquidity risk dominates in stocks lacking positive revision catalysts.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AnalystRevision"},
        {"weight": -1.0, "primitive": "Illiquidity"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "correlation", "primitive": "AnalystValue", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Operating Efficiency-Seasonality Mix",
    "mechanism": "Combining operating efficiency (CBOperProf) with return seasonality (MomSeason) and offsetting with employment growth (hire), the composite bets on firms with efficient operations and persistent return patterns but avoids those that may be over-hiring, which can indicate overexpansion and lower future returns.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "CBOperProf"},
        {"weight": 0.5, "primitive": "MomSeason"},
        {"weight": -0.5, "primitive": "hire"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "subperiod_consistency"},
      {"type": "correlation", "primitive": "AssetGrowth", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.9,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Net Payout Defensive",
    "mechanism": "By combining high net payout yield (NetPayoutYield), low beta (Beta, inversed), and consistent earnings (EarningsConsistency), the composite targets defensive stocks with shareholder-friendly capital allocation and stable earnings. This mix is expected to outperform especially when the market is down, due to the defensive tilt.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "NetPayoutYield"},
        {"weight": -1.0, "primitive": "Beta"},
        {"weight": 0.5, "primitive": "EarningsConsistency"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.9,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Credit-Duration Anomaly Hybrid",
    "mechanism": "This composite combines credit rating downgrades (CredRatDG), equity duration (EquityDuration), and residual momentum (ResidualMomentum). The hypothesis is that penalizing firms with recent downgrades and long equity duration, while favoring those with unexplained positive momentum, isolates mispriced risk ignored by standard factors.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "CredRatDG"},
        {"weight": -0.5, "primitive": "EquityDuration"},
        {"weight": 1.0, "primitive": "ResidualMomentum"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "correlation", "primitive": "LRreversal", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Intangible Growth Defensive",
    "mechanism": "Firms with high intangible investment (RDcap), low leverage (Leverage, inversed), and positive abnormal accruals (AbnormalAccruals) signify robust internal growth funded conservatively. This composite should outperform in low-volatility markets when risk aversion is low, as investors reward sustainable innovation.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "RDcap"},
        {"weight": -1.0, "primitive": "Leverage"},
        {"weight": 0.5, "primitive": "AbnormalAccruals"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 18
  }
]}
